/* ===================== STORAGE & SEEDS ===================== */
async function loadAll() {
  try {
    const r = await window.storage.get('documents');
    STATE.documents = r ? JSON.parse(r.value) : [];
    let updated = false;
    for (const d of STATE.documents) {
      if (d.type === 'advance') {
        d.formCode = 'BM 03/KT –CPC1HN';
        d.formVersionDate = '18/05/2023';
        updated = true;
      }
      if (!d.docNo) {
        d.docNo = generateRandomVoucherCode(d.type);
        updated = true;
      }
    }
    if (updated) saveDocuments();
  } catch (e) { STATE.documents = []; }

  try {
    const r = await window.storage.get('payees');
    STATE.payees = r ? JSON.parse(r.value) : [];
  } catch (e) { STATE.payees = []; }

  try {
    const r = await window.storage.get('invoices');
    STATE.invoices = r ? JSON.parse(r.value) : [];
    cleanDuplicateInvoicesInRepo();
  } catch (e) { STATE.invoices = []; }

  try {
    const r = await window.storage.get('trash');
    STATE.trash = r ? JSON.parse(r.value) : [];
  } catch (e) { STATE.trash = []; }

  try {
    const r = await window.storage.get('users');
    STATE.users = r ? JSON.parse(r.value) : [];
  } catch (e) { STATE.users = []; }

  try {
    const r = await window.storage.get('claude_api_key');
    STATE.claudeApiKey = r ? r.value : '';
  } catch (e) { STATE.claudeApiKey = ''; }

  try {
    const r = await window.storage.get('gemini_api_key');
    STATE.geminiApiKey = r ? r.value : '';
  } catch (e) { STATE.geminiApiKey = ''; }

  if (!STATE.users || STATE.users.length === 0 || STATE.users.length < 5 || !STATE.users[0].password || !STATE.users[0].pin || !STATE.users[0].email) {
    STATE.users = seedUsers();
    await saveUsers();
  }

  if (STATE.payees.length === 0 && (await isFreshInstall())) {
    STATE.payees = seedPayees();
    await savePayees();
  }

  // Parse Deep Link URL parameters (e.g. ?docId=123 or ?page=settings)
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const deepDocId = urlParams.get('docId') || urlParams.get('id');
    const deepPage = urlParams.get('page');

    if (deepDocId) {
      STATE.pendingRedirect = { page: 'detail', docId: deepDocId };
    } else if (deepPage) {
      STATE.pendingRedirect = { page: deepPage };
    }
  } catch (e) {}

  // Session check: ALWAYS require login for fresh tabs / new Chrome profiles / new devices!
  // MUST use sessionStorage for 100% isolated authentication per Chrome profile & device.
  try {
    const sessionFlag = sessionStorage.getItem('CPC1_SESSION_LOGGED_IN');
    const sessionUserId = sessionStorage.getItem('CPC1_SESSION_USER_ID');

    if (sessionFlag === 'true' && sessionUserId && STATE.users.some(u => u.id === sessionUserId)) {
      STATE.isLoggedIn = true;
      STATE.currentUserId = sessionUserId;
    } else {
      STATE.isLoggedIn = false;
      STATE.currentUserId = null;
    }
  } catch (e) {
    STATE.isLoggedIn = false;
    STATE.currentUserId = null;
  }

  // Khởi chạy đồng bộ thời gian thực đa người dùng qua Firebase Firestore
  if (window.storage && window.storage.listenRealtime && !STATE._realtimeBound) {
    STATE._realtimeBound = true;
    window.storage.listenRealtime(['documents', 'invoices', 'payees', 'trash'], (key, val) => {
      try {
        if (!val) return;
        let changed = false;

        if (key === 'documents') {
          const currentStr = JSON.stringify(STATE.documents || []);
          if (currentStr !== val) {
            STATE.documents = JSON.parse(val) || [];
            changed = true;
          }
        } else if (key === 'invoices') {
          const currentStr = JSON.stringify(STATE.invoices || []);
          if (currentStr !== val) {
            STATE.invoices = JSON.parse(val) || [];
            changed = true;
          }
        } else if (key === 'payees') {
          const currentStr = JSON.stringify(STATE.payees || []);
          if (currentStr !== val) {
            STATE.payees = JSON.parse(val) || [];
            changed = true;
          }
        } else if (key === 'trash') {
          const currentStr = JSON.stringify(STATE.trash || []);
          if (currentStr !== val) {
            STATE.trash = JSON.parse(val) || [];
            changed = true;
          }
        }

        // Không re-render lại DOM khi người dùng đang active gõ chữ trong các ô input/textarea/select để tránh giật lag, nháy màn hình và mất con trỏ
        const activeTag = document.activeElement ? document.activeElement.tagName : '';
        const isEditing = activeTag === 'INPUT' || activeTag === 'TEXTAREA' || activeTag === 'SELECT';

        if (changed && !isEditing) {
          render();
        }
      } catch (err) {
        console.warn('Realtime parse err:', err);
      }
    });
  }

  if (STATE.documents.length === 0 && (await isFreshInstall())) {
    STATE.documents = seedDocs();
    await saveDocuments();
  }
}

async function isFreshInstall() {
  try {
    const r = await window.storage.get('seeded');
    if (!r) {
      await window.storage.set('seeded', '1');
      return true;
    }
    return false;
  } catch (e) {
    return true;
  }
}

async function saveDocuments() {
  try { await window.storage.set('documents', JSON.stringify(STATE.documents)); }
  catch (e) { showToast('Lỗi lưu danh sách phiếu'); }
}
