/* ===================== DOC MODEL ===================== */
function generateRandomVoucherCode(type = 'payment') {
  const prefixMap = {
    payment: 'DNTT',
    submission: 'TTR',
    advance: 'TUG',
    reimbursement: 'HUG'
  };
  const prefix = prefixMap[type] || 'DNTT';
  const year = new Date().getFullYear();
  const randNum = Math.floor(100000 + Math.random() * 900000);
  return `${prefix}-${year}-${randNum}`;
}

function mkDoc(type, requester, extra = {}) {
  const t = DOC_TYPES[type];
  const versionDate = type === 'advance' ? '18/05/2023' : '18/09/2020';
  return Object.assign({
    id: uid('doc'),
    docNo: generateRandomVoucherCode(type),
    type,
    formCode: t.formCode,
    formVersionDate: versionDate,
    requesterId: requester.id,
    requesterName: requester.name,
    employeeCode: requester.employeeCode,
    department: requester.department,
    createdAt: new Date().toISOString(),
    documentDate: new Date().toISOString().slice(0, 10),
    status: 'draft',
    currency: 'VND',
    paymentMethod: 'cash',
    payeeId: null,
    payeeName: '',
    payeeAccount: '',
    payeeBank: '',
    items: [],
    advanceRefs: [],
    advancedItems: [],
    spentItems: [],
    attachments: [],
    signedAttachmentId: null,
    history: [{ at: new Date().toISOString(), action: 'Tạo phiếu (nháp)', by: requester.name }]
  }, extra);
}

function computeTotal(doc) {
  if (!doc) return 0;
  if (doc.type === 'reimbursement') {
    return (doc.spentItems || []).reduce((s, i) => s + (Number(i.amount) || 0), 0);
  }
  return (doc.items || []).reduce((s, i) => s + (Number(i.amount) || 0), 0);
}

function computeAdvancedTotal(doc) {
  if (!doc) return 0;
  return (doc.advancedItems || []).reduce((s, i) => s + (Number(i.amount) || 0), 0);
}

