function showToast(msg) {
  const t = document.getElementById('toast');
  if (!t) return;
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(window._toastTimer);
  window._toastTimer = setTimeout(() => t.classList.remove('show'), 2600);
}

function showAlertModal(title, message) {
  const existing = document.getElementById('alert-modal-overlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.id = 'alert-modal-overlay';
  overlay.className = 'modal-overlay';
  overlay.innerHTML = `
    <div class="modal-box">
      <h3>⚠️ ${title}</h3>
      <p>${message}</p>
      <button class="btn btn-stamp" id="alert-modal-close-btn" style="width:100%;">Đã hiểu</button>
    </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.getElementById('alert-modal-close-btn').addEventListener('click', () => overlay.remove());
}

function showConfirmModal(title, message, onConfirm) {
  const existing = document.getElementById('confirm-modal-overlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.id = 'confirm-modal-overlay';
  overlay.className = 'modal-overlay';
  overlay.innerHTML = `
    <div class="modal-box">
      <h3>${title}</h3>
      <p>${message}</p>
      <div style="display:flex;gap:10px;">
        <button class="btn btn-outline" id="confirm-modal-cancel-btn" style="flex:1;">Huỷ</button>
        <button class="btn btn-stamp" id="confirm-modal-ok-btn" style="flex:1;">Xác nhận</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.getElementById('confirm-modal-cancel-btn').addEventListener('click', () => overlay.remove());
  document.getElementById('confirm-modal-ok-btn').addEventListener('click', () => {
    overlay.remove();
    onConfirm();
  });
}

function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = (e) => {
      const dataUrl = e.target.result;
      if (file.type && file.type.startsWith('image/')) {
        const img = new Image();
        img.onload = () => {
          const maxDim = 1600;
          let width = img.width;
          let height = img.height;
          if (width > maxDim || height > maxDim) {
            if (width > height) {
              height = Math.round((height * maxDim) / width);
              width = maxDim;
            } else {
              width = Math.round((width * maxDim) / height);
              height = maxDim;
            }
          }
          const canvas = document.createElement('canvas');
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.8));
        };
        img.onerror = () => resolve(dataUrl);
        img.src = dataUrl;
      } else {
        resolve(dataUrl);
      }
    };
    r.onerror = () => reject(r.error);
    r.readAsDataURL(file);
  });
}

function monthKey(dateStr) {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return 'unknown';
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

function monthLabel(key) {
  if (key === 'unknown') return 'Không rõ';
  const [y, m] = key.split('-');
  return `Tháng ${m}/${y}`;
}

/* ===================== PDF PRINT & GENERATION ===================== */
async function printDoc(doc) {
  if (!window.html2canvas || !(window.jspdf && window.jspdf.jsPDF)) {
    showAlertModal('Đang tải thư viện', 'Thư viện tạo PDF đang sẵn sàng, vui lòng đợi vài giây rồi thử lại.');
    return;
  }
  showToast('Đang tạo file PDF bản in…');
  const MM_PX = 3.7795275591;
  const A5W = 148 * MM_PX, A5H = 210 * MM_PX;
  const A4W = 210 * MM_PX, A4H = 297 * MM_PX;

  const printCSS = `
    .pdf-render-root{background:#fff;font-family:'Source Serif 4', Georgia, serif;}
    .pdf-render-root .doc-preview{padding:16px 20px;max-width:100%;border:none;box-shadow:none;}
    .pdf-render-root .doc-title-red{font-size:16px;margin:4px 0 10px;}
    .pdf-render-root .doc-subject{font-size:11px;margin-bottom:12px;}
    .pdf-render-root .doc-meta-line{font-size:11px;margin-bottom:4px;}
    .pdf-render-root .doc-meta-indent{font-size:11px;padding-left:18px;margin-bottom:2px;}
    .pdf-render-root .items-table{margin:10px 0;}
    .pdf-render-root .items-table td, .pdf-render-root .items-table th{font-size:10px;padding:5px 6px;}
    .pdf-render-root .doc-date-line{font-size:10.5px;margin:12px 0 4px;}
    .pdf-render-root .letterhead-code{font-size:9px;}
    .pdf-render-root .logo-img{height:36px;}
    .pdf-render-root .sign-grid{margin-top:14px;display:flex;border:none;}
    .pdf-render-root .sign-box{flex:1;font-size:9px;padding:6px 4px 10px;border:none;}
    .pdf-render-root .sign-box .role{font-size:9px;margin-bottom:6px;}
    .pdf-render-root .sign-box .name{font-size:9px;}
    .pdf-render-root .sign-space{height:60px;}
    .pdf-render-root .stamp-mark{width:36px;height:36px;font-size:7px;border-width:2px;margin:0 auto;}
    .pdf-render-root .diff-box{font-size:10px;padding:8px 10px;}
  `;

  const container = document.createElement('div');
  container.className = 'pdf-render-root';
  container.style.cssText = `position:fixed;left:-9999px;top:0;width:${A5W}px;background:#fff;`;
  container.innerHTML = `<style>${printCSS}</style>` + renderPaperPreview(doc);
  document.body.appendChild(container);
  await new Promise(r => setTimeout(r, 80));

  let pageFormat = 'a5', pageWpx = A5W, pageHpx = A5H, pageWmm = 148, pageHmm = 210;
  if (container.scrollHeight > A5H) {
    pageFormat = 'a4'; pageWpx = A4W; pageHpx = A4H; pageWmm = 210; pageHmm = 297;
    container.style.width = pageWpx + 'px';
    await new Promise(r => setTimeout(r, 80));
  }

  try {
    const canvas = await html2canvas(container, { scale: 2.5, backgroundColor: '#ffffff', windowWidth: pageWpx });
    document.body.removeChild(container);

    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF({ unit: 'mm', format: pageFormat, orientation: 'portrait' });
    const imgData = canvas.toDataURL('image/jpeg', 0.94);
    const imgWmm = pageWmm;
    const imgHmm = canvas.height * imgWmm / canvas.width;

    if (imgHmm <= pageHmm) {
      pdf.addImage(imgData, 'JPEG', 0, 0, imgWmm, imgHmm);
    } else {
      let heightLeftMm = imgHmm;
      let position = 0;
      pdf.addImage(imgData, 'JPEG', 0, position, imgWmm, imgHmm);
      heightLeftMm -= pageHmm;
      while (heightLeftMm > 0) {
        position -= pageHmm;
        pdf.addPage();
        pdf.addImage(imgData, 'JPEG', 0, position, imgWmm, imgHmm);
        heightLeftMm -= pageHmm;
      }
    }

    const safeName = (doc.requesterName || 'phieu').replace(/[^\p{L}\p{N}]+/gu, '_');
    const fileName = `${DOC_TYPES[doc.type].short}_${safeName}_${doc.documentDate || ''}.pdf`;
    pdf.save(fileName);
    showToast(`✓ Đã tải file PDF (khổ ${pageFormat.toUpperCase()})`);
  } catch (e) {
    if (container.parentNode) document.body.removeChild(container);
    console.error(e);
    showAlertModal('Lỗi xuất PDF', 'Có lỗi khi tạo file PDF. Chi tiết: ' + (e.message || e));
  }
}

/* ===================== ACTIONS ===================== */
async function submitDoc(doc) {
  doc.status = 'pending_signature';
  doc.history.push({ at: new Date().toISOString(), action: 'Trình ký', by: currentUser().name });
  await saveDocuments();
  showToast('Đã trình ký — đang chờ ký duyệt trên bản giấy');
  render();
}

function cancelSignature(doc) {
  showConfirmModal('Huỷ trình ký?', 'Đưa phiếu về trạng thái Nháp để chỉnh sửa?', async () => {
    doc.status = 'draft';
    doc.history.push({ at: new Date().toISOString(), action: 'Huỷ trình ký, quay về nháp', by: currentUser().name });
    await saveDocuments();
    showToast('Đã đưa phiếu về Nháp');
    render();
  });
}

async function uploadSignedCopy(doc, file) {
  if (!file) return;
  const isValid = file.type === 'application/pdf' || file.type.startsWith('image/') || /\.(pdf|jpg|jpeg|png|webp|bmp)$/i.test(file.name);
  if (!isValid) { showAlertModal('Sai định dạng', 'Vui lòng chọn file PDF hoặc Ảnh scan (.jpg, .png, .pdf).'); return; }
  if (file.size > MAX_ATTACH_BYTES) { showAlertModal('File quá lớn', 'File vượt quá dung lượng cho phép (>3.5MB).'); return; }
  try {
    if (doc.signedAttachmentId) { await removeAttachmentSilent(doc, doc.signedAttachmentId); }
    const dataUrl = await readFileAsDataURL(file);
    const attId = uid('att');
    await window.storage.set('attachment:' + attId, dataUrl, true);
    doc.attachments.push({
      id: attId,
      fileName: file.name,
      mimeType: file.type || (file.name.endsWith('.pdf') ? 'application/pdf' : 'image/jpeg'),
      size: file.size,
      uploadedAt: new Date().toISOString(),
      uploadedBy: currentUser().name
    });
    doc.signedAttachmentId = attId;
    doc.status = 'signed';
    doc.history.push({ at: new Date().toISOString(), action: 'Tải lên bản đã ký — Hoàn tất', by: currentUser().name });
    await saveDocuments();
    showToast('✓ Đã cập nhật bản ký — Phiếu hoàn tất');
    STATE.previewAttachmentId = attId;
    render();
  } catch (e) {
    console.error(e);
    showToast('Lỗi khi tải file lên');
  }
}

function removeSignedCopy(doc) {
  showConfirmModal('Gỡ bản đã ký?', 'Gỡ bản đã ký hiện tại? Phiếu sẽ quay về trạng thái Chờ ký.', async () => {
    if (doc.signedAttachmentId) { await removeAttachmentSilent(doc, doc.signedAttachmentId); }
    doc.signedAttachmentId = null;
    doc.status = 'pending_signature';
    doc.history.push({ at: new Date().toISOString(), action: 'Gỡ bản đã ký, chờ tải lại', by: currentUser().name });
    await saveDocuments();
    showToast('Đã gỡ bản đã ký');
    render();
  });
}

function deleteDoc(id) {
  const doc = STATE.documents.find(d => d.id === id);
  if (!doc) return;
  const isAuthorizedAdmin = ['admin', 'dept_head', 'chief_accountant', 'director'].includes(currentUser().role);
  const isOwner = doc.requesterId === currentUser().id;

  if (!isAuthorizedAdmin && !(doc.status === 'draft' && isOwner)) {
    showAlertModal('Quyền Hạn Hạn Chế', 'Chỉ Trưởng nhóm hoặc Admin mới được phép xóa phiếu đang chờ ký!');
    return;
  }

  showConfirmModal('Chuyển phiếu vào Thùng rác?', `Bạn có chắc chắn muốn xoá phiếu ${doc.docNo || doc.formCode}? Phiếu sẽ được chuyển vào Thùng rác và có thể khôi phục lại bất kỳ lúc nào.`, async () => {
    const trashDoc = JSON.parse(JSON.stringify(doc));
    trashDoc.deletedAt = new Date().toISOString();
    trashDoc.deletedBy = currentUser().name;
    trashDoc.itemType = 'document';

    if (!STATE.trash) STATE.trash = [];
    STATE.trash.unshift(trashDoc);
    await saveTrash();

    STATE.documents = STATE.documents.filter(d => d.id !== id);
    await saveDocuments();
    STATE.page = 'list';
    render();
    showToast('✓ Đã chuyển phiếu vào Thùng rác thành công!');
  });
}

function duplicateDoc(doc) {
  const copy = JSON.parse(JSON.stringify(doc));
  copy.id = uid('doc');
  copy.status = 'draft';
  copy.createdAt = new Date().toISOString();
  copy.documentDate = new Date().toISOString().slice(0, 10);
  copy.signedAttachmentId = null;
  copy.attachments = [];
  (copy.items || []).forEach(i => { i.attachmentId = null; });
  (copy.spentItems || []).forEach(i => { i.attachmentId = null; });
  copy.history = [{ at: new Date().toISOString(), action: 'Tạo từ bản sao của phiếu cũ', by: currentUser().name }];
  STATE.draftForm = copy;
  STATE.page = 'form';
  STATE.formType = copy.type;
  STATE.selectedId = null;
  render();
}

