function cleanDuplicateInvoicesInRepo() {
  if (!STATE.invoices || STATE.invoices.length === 0) return;

  let patched = false;
  for (const r of STATE.invoices) {
    if (!r.seriesNo || r.seriesNo.trim() === '') {
      if (r.invoiceNumber === '1762375' || (r.fileName && /308788310630|BIÊN\s*LAI|CSHT/i.test(r.fileName))) {
        r.seriesNo = 'VC-24E';
        patched = true;
      }
    }
  }

  const seen = new Set();
  const filtered = [];
  for (const r of STATE.invoices) {
    const invNum = (r.invoiceNumber || '').trim();
    const sNo = (r.seriesNo || '').trim().toUpperCase();
    if (invNum) {
      const key = `${sNo}|${invNum}`;
      if (!seen.has(key)) {
        seen.add(key);
        filtered.push(r);
      }
    } else {
      filtered.push(r);
    }
  }
  if (patched || filtered.length < STATE.invoices.length) {
    STATE.invoices = filtered;
    saveInvoices();
  }
}

function isSameInvoiceNo(inv1, inv2) {
  if (!inv1 || !inv2) return false;
  const s1 = inv1.trim().toLowerCase();
  const s2 = inv2.trim().toLowerCase();
  if (s1 === s2) return true;

  const parts1 = s1.split(/[|]/).map(p => p.trim()).filter(Boolean);
  const parts2 = s2.split(/[|]/).map(p => p.trim()).filter(Boolean);

  const num1 = parts1[parts1.length - 1];
  const num2 = parts2[parts2.length - 1];

  const series1 = parts1.length > 1 ? parts1[0] : '';
  const series2 = parts2.length > 1 ? parts2[0] : '';

  if (num1 && num2 && num1 === num2 && num1.length >= 4) {
    if (!series1 || !series2 || series1 === series2) {
      return true;
    }
  }
  return false;
}

function findDuplicateInvoiceUsage(invoiceNo, excludeDocId) {
  if (!invoiceNo || !invoiceNo.trim()) return null;
  for (const d of STATE.documents) {
    if (d.id === excludeDocId) continue;
    if (d.status === 'cancelled') continue;
    const arr = [...(d.items || []), ...(d.spentItems || [])];
    const match = arr.find(it => it.invoiceNo && isSameInvoiceNo(it.invoiceNo, invoiceNo));
    if (match) return d;
  }
  return null;
}

function playWarningChime() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const osc1 = ctx.createOscillator();
    const osc2 = ctx.createOscillator();
    const gain = ctx.createGain();

    osc1.type = 'sine';
    osc2.type = 'triangle';
    osc1.frequency.setValueAtTime(880, ctx.currentTime);
    osc2.frequency.setValueAtTime(1760, ctx.currentTime);

    gain.gain.setValueAtTime(0.3, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.45);

    osc1.connect(gain);
    osc2.connect(gain);
    gain.connect(ctx.destination);

    osc1.start();
    osc2.start();
    osc1.stop(ctx.currentTime + 0.45);
    osc2.stop(ctx.currentTime + 0.45);
  } catch (e) {}
}

