  if (bMap.size > 1) {
    const detailsList = Array.from(bMap.entries()).map(([name, invs]) => `🏢 <b>${name}</b> (${invs.join(', ')})`).join(' &nbsp;·&nbsp; ');

    return `
      <div style="background:#FEF3C7;border:1.5px solid #F59E0B;border-radius:10px;padding:12px 16px;margin:12px 0 16px;display:flex;align-items:flex-start;gap:12px;color:#92400E;font-size:13px;line-height:1.45;box-shadow:0 3px 10px rgba(245,158,11,0.12);">
        <span style="font-size:22px;line-height:1;">⚠️</span>
        <div style="flex:1;">
          <div style="font-weight:700;font-size:13.5px;color:#B45309;margin-bottom:4px;">
            Cảnh báo: ĐNTT bao gồm hoá đơn từ ${bMap.size} Đơn vị thụ hưởng / Bên bán khác nhau!
          </div>
          <div style="color:#78350F;margin-bottom:4px;">${detailsList}</div>
          <div style="font-size:12px;color:#92400E;font-style:italic;">
            📌 Lưu ý: Vui lòng kiểm tra kỹ xem có nên tách thành từng phiếu ĐNTT riêng biệt cho từng Nhà cung cấp để đảm bảo chuyển khoản chính xác tài khoản thụ hưởng!
          </div>
        </div>
      </div>`;
  }
