function getGlobalDuplicateWarnings() {
  const warnings = [];
  const seenMap = {};

  for (const d of STATE.documents) {
    if (d.status === 'cancelled') continue;
    const items = [...(d.items || []), ...(d.spentItems || [])];
    for (const it of items) {
      if (!it.invoiceNo || !it.invoiceNo.trim()) continue;
      const invNo = it.invoiceNo.trim();
      const key = invNo.toLowerCase();
      if (!seenMap[key]) seenMap[key] = [];
      seenMap[key].push({ doc: d, item: it, invoiceNo: invNo });
    }
  }

  for (const key in seenMap) {
    const list = seenMap[key];
    if (list.length > 1) {
      const docIds = new Set();
      const uniqueDocs = [];
      for (const entry of list) {
        if (!docIds.has(entry.doc.id)) {
          docIds.add(entry.doc.id);
          uniqueDocs.push(entry);
        }
      }
      if (uniqueDocs.length > 1) {
        warnings.push({
          invoiceNo: list[0].invoiceNo,
          entries: uniqueDocs
        });
      }
    }
  }

  return warnings;
}

function renderGlobalDuplicateWarningBannerHtml() {
  const globalWarnings = getGlobalDuplicateWarnings();
  if (globalWarnings.length === 0) return '';

  const totalDuplicates = globalWarnings.length;

  const warningListHtml = globalWarnings.map(g => {
    const docsDetailHtml = g.entries.map(e => {
      const typeLabel = DOC_TYPES[e.doc.type] ? DOC_TYPES[e.doc.type].label : 'Phiếu';
      const statusLabel = STATUS_LABEL[e.doc.status] || e.doc.status;
      const code = e.doc.docNo || e.doc.formCode;
      return `mã phiếu <b>${code}</b> (${typeLabel}) lập ngày ${fmtDate(e.doc.documentDate)} [<span style="color:#C2410C;font-weight:700;">${statusLabel}</span> - ${e.doc.requesterName}]`;
    }).join(' và ');

    return `<li style="margin-bottom:6px;">Hoá đơn <b>"${g.invoiceNo}"</b> ➔ Đã nằm trong <b>${g.entries.length} phiếu</b>: ${docsDetailHtml}</li>`;
  }).join('');

  return `
    <div class="dup-alert-banner global-dup-alert" style="background:#FFF1F2;border:1.5px solid #F43F5E;border-radius:12px;padding:16px 20px;margin:16px 0;display:flex;align-items:flex-start;gap:14px;box-shadow:0 4px 16px rgba(244,63,94,0.15);animation:fadeIn 0.25s ease;">
      <span style="font-size:26px;line-height:1;">🚨</span>
      <div style="flex:1;">
        <b style="color:#9F1239;font-size:15px;display:block;margin-bottom:4px;">🚨 CẢNH BÁO TRÙNG LẶP HOÁ ĐƠN LÀM ĐNTT</b>
        <p style="margin:0 0 8px;font-size:13px;color:#881337;line-height:1.5;">
          Phát hiện <b>${totalDuplicates} hoá đơn</b> bị trùng lặp. Vui lòng kiểm tra lại trước khi trình ký để tránh chi trả 2 lần:
        </p>
        <ul style="margin:0;padding-left:20px;font-size:13px;color:#9F1239;line-height:1.55;">
          ${warningListHtml}
        </ul>
      </div>
    </div>`;
}

