function getAdvanceOverdueDays(doc) {
  if (!doc || doc.type !== 'advance' || doc.status !== 'signed') return 0;
  const isReimbursed = STATE.documents.some(r => r.type === 'reimbursement' && (r.advanceRefs || []).includes(doc.id));
  if (isReimbursed) return 0;

  const docDate = new Date(doc.documentDate || doc.createdAt);
  const now = new Date();
  const diffDays = Math.floor((now.getTime() - docDate.getTime()) / (1000 * 3600 * 24));
  return diffDays > 30 ? diffDays : 0;
}

function getOverdueAdvanceRequests(userOnly = false) {
  const u = currentUser();
  const now = new Date();
  return getAccessibleDocuments().filter(d => {
    if (d.type !== 'advance' || d.status !== 'signed') return false;
    if (userOnly && d.employeeCode !== u.code && d.requesterId !== u.id) return false;
    const isReimbursed = STATE.documents.some(r => r.type === 'reimbursement' && (r.advanceRefs || []).includes(d.id));
    if (isReimbursed) return false;

    const docDate = new Date(d.documentDate || d.createdAt);
    const diffDays = Math.floor((now.getTime() - docDate.getTime()) / (1000 * 3600 * 24));
    return diffDays > 30;
  }).map(d => {
    const docDate = new Date(d.documentDate || d.createdAt);
    const diffDays = Math.floor((now.getTime() - docDate.getTime()) / (1000 * 3600 * 24));
    return { doc: d, daysOverdue: diffDays };
  });
}

