function updateInvoiceTableView() {
  const records = getFilteredInvoices();
  const selected = STATE.selectedInvoiceIds || [];
  const wrapper = document.getElementById('invoice-table-wrapper');
  if (wrapper) {
    wrapper.innerHTML = renderInvoiceTableHtml(records, selected);
    attachInvoiceTableHandlers();
  }
  updateInvoiceActionBar();

  const topScroll = document.getElementById('invoice-top-scroll');
  const inner = document.getElementById('invoice-top-scroll-inner');
  if (topScroll && inner && wrapper) {
    topScroll.style.display = records.length > 0 ? '' : 'none';
    const table = wrapper.querySelector('table');
    inner.style.width = (table ? table.scrollWidth : 0) + 'px';
  }
}

async function reparseAllExistingInvoices() {
  if (!STATE.invoices || STATE.invoices.length === 0) {
    showToast('Chưa có hoá đơn nào trong kho.');
    return;
  }
  showConfirmModal(
    'Quét lại dữ liệu hoá đơn?',
    `Hệ thống sẽ chạy bộ trích xuất thông minh nâng cấp cho toàn bộ ${STATE.invoices.length} hoá đơn trong kho để tự động nhận diện lại Ký hiệu, Số HĐ, Tiền, Loại tiền (VNĐ/USD) và Tên hàng hoá. Bạn có muốn tiếp tục?`,
    async () => {
      STATE.invoiceUploading = true;
      render();
      let count = 0;
      for (const r of STATE.invoices) {
        if (!r.attachmentId) continue;
        count++;
        showToast(`Đang quét lại hoá đơn ${count}/${STATE.invoices.length}…`);
        try {
          const stored = await window.storage.get('attachment:' + r.attachmentId, true);
          if (!stored || !stored.value) continue;
          const dataUrl = stored.value;
          const res = await fetch(dataUrl);
          const blob = await res.blob();
          const file = new File([blob], r.fileName || 'invoice.pdf', { type: 'application/pdf' });
          const extracted = await extractInvoiceDataFromPdfFile(file, dataUrl);
          if (extracted) {
            if (extracted.seriesNo) r.seriesNo = extracted.seriesNo;
            if (extracted.invoiceNumber) r.invoiceNumber = extracted.invoiceNumber;
            if (extracted.date) r.date = extracted.date;
            if (extracted.amount) r.amount = Number(extracted.amount) || r.amount;
            if (extracted.currency) r.currency = extracted.currency;
            if (extracted.description) r.note = extracted.description;
            if (extracted.sellerName) r.beneficiaryName = extracted.sellerName;
          }
        } catch (err) {
          console.warn('Lỗi reparse invoice:', r.fileName, err);
        }
      }
      await saveInvoices();
      STATE.invoiceUploading = false;
      showToast(`✓ Đã cập nhật xong dữ liệu cho ${count} hoá đơn!`);
      render();
    }
  );
}

function bindFormInputs() {
  if (STATE.page !== 'form') return;
  const doc = STATE.draftForm;
  if (!doc) return;

  const bind = (id, field) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('input', e => {
      doc[field] = e.target.value;
      refreshDynamicParts();
    });
  };

  bind('f-documentDate', 'documentDate');
  bind('f-contentSummary', 'contentSummary');
  bind('f-subject', 'subject');
  bind('f-reason', 'reason');
  bind('f-paymentDeadline', 'paymentDeadline');
  bind('f-department', 'department');

  const empSel = document.getElementById('f-employeeCode');
  if (empSel) empSel.addEventListener('change', e => {
    doc.employeeCode = e.target.value;
    const emp = EMPLOYEE_DIRECTORY.find(x => x.code === doc.employeeCode);
    if (emp) {
      doc.requesterName = emp.name;
      doc.department = emp.department;
    }
    render();
  });

  const cur = document.getElementById('f-currency');
  if (cur) cur.addEventListener('change', e => {
    doc.currency = e.target.value;
    render();
  });

  const payeeSel = document.getElementById('f-payeeId');
  if (payeeSel) payeeSel.addEventListener('change', e => {
    doc.payeeId = e.target.value || null;
    const p = STATE.payees.find(pp => pp.id === doc.payeeId);
    doc.payeeName = p ? p.name : '';
    doc.payeeAccount = p ? p.accountNumber : '';
    doc.payeeBank = p ? p.bankName : '';
    const infoBox = document.getElementById('payee-info-box');
    if (infoBox) {
      if (p) {
        infoBox.style.display = '';
        infoBox.innerHTML = `<b>${p.name}</b><br>Số TK: <b>${p.accountNumber}</b> · ${p.bankName}`;
      } else {
        infoBox.style.display = 'none';
        infoBox.innerHTML = '';
      }
    }
    refreshDynamicParts();
  });

  document.querySelectorAll('[data-paymethod]').forEach(el => el.addEventListener('click', () => {
    doc.paymentMethod = el.dataset.paymethod;
    render();
  }));

  document.querySelectorAll('[data-item]').forEach(el => el.addEventListener('input', e => {
    const idx = Number(el.dataset.item), field = el.dataset.field;
    doc.items[idx][field] = field === 'amount' ? Number(e.target.value) : e.target.value;
    if (field === 'invoiceNo') {
      renderFormDuplicateBanner(doc);
    }
    refreshDynamicParts();
  }));

  document.querySelectorAll('[data-item][data-field="invoiceNo"]').forEach(el => el.addEventListener('blur', () => {
    checkDuplicateInvoice(doc, el.value, el);
  }));

  document.querySelectorAll('[data-delitem]').forEach(el => el.addEventListener('click', async () => {
    const idx = Number(el.dataset.delitem);
    const row = doc.items[idx];
    if (row && row.attachmentId) { await removeAttachmentSilent(doc, row.attachmentId); }
    doc.items.splice(idx, 1);
    render();
  }));

  const addItemBtn = document.getElementById('add-item');
  if (addItemBtn) addItemBtn.addEventListener('click', () => {
    doc.items.push(blankItem(doc.type));
    render();
  });

  // Reimbursement Advance Selection
  document.querySelectorAll('[data-adv]').forEach(el => el.addEventListener('change', () => {
    const advId = el.dataset.adv;
    if (el.checked) {
      if (!doc.advanceRefs.includes(advId)) doc.advanceRefs.push(advId);
      const advDoc = STATE.documents.find(d => d.id === advId);
      if (advDoc && doc.advanceRefs.length === 1) { doc.currency = advDoc.currency; }
    } else {
      doc.advanceRefs = doc.advanceRefs.filter(x => x !== advId);
    }
    doc.advancedItems = doc.advanceRefs.flatMap(id => {
      const a = STATE.documents.find(d => d.id === id);
      return a ? a.items : [];
    });
    render();
  }));

  document.querySelectorAll('[data-spent]').forEach(el => el.addEventListener('input', e => {
    const idx = Number(el.dataset.spent), field = el.dataset.field;
    doc.spentItems[idx][field] = field === 'amount' ? Number(e.target.value) : e.target.value;
    refreshDynamicParts();
  }));

  document.querySelectorAll('[data-spent][data-field="invoiceNo"]').forEach(el => el.addEventListener('blur', () => {
    checkDuplicateInvoice(doc, el.value, el);
  }));

  document.querySelectorAll('[data-delspent]').forEach(el => el.addEventListener('click', async () => {
    const idx = Number(el.dataset.delspent);
    const row = doc.spentItems[idx];
    if (row && row.attachmentId) { await removeAttachmentSilent(doc, row.attachmentId); }
    doc.spentItems.splice(idx, 1);
    render();
  }));

  const addSpentBtn = document.getElementById('add-spent');
  if (addSpentBtn) addSpentBtn.addEventListener('click', () => {
    doc.spentItems.push(blankItem('reimbursement'));
    render();
  });

  const saveDraftBtn = document.getElementById('save-draft');
  if (saveDraftBtn) saveDraftBtn.addEventListener('click', async () => { await persistForm(false); });
  const submitBtn = document.getElementById('submit-doc');
  if (submitBtn) submitBtn.addEventListener('click', async () => { await persistForm(true); });
}

function refreshDynamicParts() {
  const doc = STATE.draftForm;
  if (!doc) return;
  const total = computeTotal(doc);
  const totalEl = document.getElementById('form-total-amt');
  if (totalEl) totalEl.textContent = fmtMoney(total, doc.currency);
  const wordsEl = document.getElementById('form-total-words');
  if (wordsEl) wordsEl.textContent = 'Bằng chữ: ' + numberToWords(total, doc.currency);

  if (doc.type === 'reimbursement') {
    const advancedTotal = computeAdvancedTotal(doc);
    const spentTotal = computeTotal(doc);
    const diff = advancedTotal - spentTotal;
    const diffEl = document.getElementById('form-diff-box');
    if (diffEl) {
      diffEl.className = 'diff-box ' + (diff === 0 ? 'diff-zero' : diff > 0 ? 'diff-surplus' : 'diff-shortfall');
      diffEl.textContent = diff === 0
        ? 'Đã chi đúng bằng số tạm ứng'
        : diff > 0
          ? `Tạm ứng chi không hết: còn dư ${fmtMoney(diff, doc.currency)}`
          : `Chi vượt số tạm ứng: cần hoàn thêm ${fmtMoney(-diff, doc.currency)}`;
    }
  }

  refreshCashLimitWarning(doc);
}

async function persistForm(goSubmit) {
  const doc = STATE.draftForm;

  // Kiểm tra nảy popup cảnh báo trùng lặp hoá đơn ĐNTT kèm âm thanh ting ting
  if (getFormDuplicateWarnings(doc).length > 0) {
    showFormDuplicatePopupModal(doc);
    return;
  }

  const total = computeTotal(doc);
  if (total <= 0) {
    showAlertModal('Số tiền không hợp lệ', 'Tổng số tiền của phiếu phải lớn hơn 0. Vui lòng kiểm tra lại các dòng chi tiết.');
    return;
  }

  // Cảnh báo & Khóa KHÔNG CHO PHÉP Lưu nháp hoặc Trình ký nếu chi tiền mặt > 5 triệu VNĐ
  const isCash = doc.paymentMethod === 'cash' || !doc.paymentMethod;
  const isVnd = !doc.currency || doc.currency === 'VND';
  if (isCash && isVnd && total > 5000000) {
    showCashLimitPopupModal(doc);
    return; // Chặn triệt để cả Lưu nháp và Trình ký!
  }

  await executePersistForm(goSubmit);
}

async function executePersistForm(goSubmit) {
  const doc = STATE.draftForm;
  const existingIdx = STATE.documents.findIndex(d => d.id === doc.id);
  if (existingIdx >= 0) STATE.documents[existingIdx] = doc;
  else STATE.documents.push(doc);

  await saveDocuments();
  if (goSubmit) {
    await submitDoc(doc);
  }
  STATE.selectedId = doc.id;
  STATE.page = 'detail';
  STATE.draftForm = null;
  render();
  showToast(goSubmit ? 'Đã trình ký thành công' : 'Đã lưu nháp');
}

/* ===================== INIT ===================== */
async function initApp() {
  const app = document.getElementById('app');
  if (app) app.innerHTML = '<div style="padding:40px;font-family:Inter,sans-serif;color:#0A2F52;font-weight:600;">Đang khởi động hệ thống CPC1...</div>';
  await loadAll();
  checkAndDispatchWeeklyOverdueAdvanceEmails();
  render();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}
